    10→/// Top-level isolate function for image resize (required for compute)
    11→Uint8List _resizeImageIsolate(Map<String, dynamic> params) {
    12→  final imageBytes = params['imageBytes'] as Uint8List;
    13→  final targetSize = params['targetSize'] as int;
    14→
    15→  var image = img.decodeImage(imageBytes);
    16→  if (image == null) {
    17→    throw Exception('Failed to decode image');
    18→  }
    19→
    20→  // Resize to target size if not already that size
    21→  if (image.width != targetSize || image.height != targetSize) {
    22→    image = img.copyResize(
    23→      image,
    24→      width: targetSize,
    25→      height: targetSize,
    26→      interpolation: img.Interpolation.cubic,
    27→    );
    28→  }
    29→
    30→  // Encode as PNG (lossless intermediate format)
    31→  return Uint8List.fromList(img.encodePng(image));
    32→}
