    20→  Future<void> exportAll() async {
    21→    final groups = _ref.read(groupsProvider);
    22→    final exportService = _ref.read(exportServiceProvider);
    23→    final nanoBananaService = _ref.read(nanoBananaServiceProvider);
    24→    final colorizedNotifier = _ref.read(colorizedImagesProvider.notifier);
    25→    final imageCache = _ref.read(imageCacheServiceProvider);
    26→
    27→    // Prepare export data: for each group, export only the selected generation
    28→    final exportData = <ExportImageData>[];
    29→
    30→    for (final group in groups) {
    31→      // Get the selected generation for this group
    32→      final selectedGeneration = _ref.read(selectedGenerationProvider(group.id));
    33→
    34→      // Get the colorized image for this group's selected generation
    35→      final image = colorizedNotifier.getByGroupAndGeneration(group.id, selectedGeneration);
    36→      if (image == null) continue;
    37→
    38→      // Get base colorized bytes from cache
    39→      final baseColorizedBytes = imageCache.getBaseColorizedImage(image.id);
    40→      if (baseColorizedBytes == null) continue;
    41→
    42→      // Use generation-specific adjustment key
    43→      final adjustmentKey = '${group.id}:$selectedGeneration';
    44→      final adjustments = _ref.read(groupAdjustmentsProvider(adjustmentKey));
    45→
    46→      // Generate transparent background version
    47→      final transparentBytes = await nanoBananaService.applyAdjustments(
    48→        baseColorizedBytes: baseColorizedBytes,
    49→        hue: adjustments.hue,
    50→        saturation: adjustments.saturation,
    51→        brightness: adjustments.brightness,
    52→        contrast: adjustments.contrast,
    53→        sharpness: adjustments.sharpness,
    54→        useWhiteBackground: false,
    55→      );
    56→
    57→      // Generate zoom version (using zoomed SILK template + zoomed carton)
    58→      final zoomBytes = await nanoBananaService.generateZoomImage(
    59→        hexColor: image.appliedHex,
    60→        hue: adjustments.hue,
    61→        saturation: adjustments.saturation,
    62→        brightness: adjustments.brightness,
    63→        contrast: adjustments.contrast,
    64→        sharpness: adjustments.sharpness,
    65→      );
    66→
    67→      // Generate front version (using Kolut in gorila spodaj + CartonGorilla)
    68→      final frontBytes = await nanoBananaService.generateFrontImage(
    69→        hexColor: image.appliedHex,
    70→        hue: adjustments.hue,
    71→        saturation: adjustments.saturation,
    72→        brightness: adjustments.brightness,
    73→        contrast: adjustments.contrast,
    74→        sharpness: adjustments.sharpness,
    75→      );
