    77→      exportData.add(ExportImageData(
    78→        groupName: group.name,
    79→        sku: group.sku,
    80→        transparentBytes: transparentBytes,
    81→        zoomBytes: zoomBytes,
    82→        frontBytes: frontBytes,
    83→      ));
    84→    }
